<script setup lang="ts">
import {localize} from './localization';

import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import type {AssistantConnection} from '../../../packages/schema/index';
const props=defineProps<{language:'zh'|'en'}>(),zh=computed(()=>props.language==='zh'),connection=ref<AssistantConnection>(),busy=ref(false),error=ref(''),expanded=ref(false),revealed=ref(false);let timer:ReturnType<typeof setInterval>;
async function refresh(){if(busy.value)return;const r=await window.fpcad.assistant('status');if(r.ok)connection.value=r.connection;}
async function toggle(){busy.value=true;error.value='';try{const r=await window.fpcad.assistant(connection.value?.enabled?'disable':'enable');if(r.ok){connection.value=r.connection;expanded.value=r.connection.enabled;revealed.value=false;}else error.value=r.error.code;}catch{error.value='ASSISTANT_CONNECTION_FAILED';}finally{busy.value=false;}}
onMounted(()=>{void refresh();timer=setInterval(()=>void refresh(),3000);});onBeforeUnmount(()=>clearInterval(timer));
</script>
<template><div class="assistant-connection"><label><input type="checkbox" :checked="!!connection?.enabled" :disabled="busy" @change="toggle">{{zh?'允许 AI 助手连接':localize('Allow local AI assistant')}}</label><span>{{connection?.connected?(zh?'本机助手已连接':localize('Local assistant connected')):connection?.enabled?(zh?'等待本机助手连接':localize('Waiting for local assistant')):(zh?'AI 助手未连接':localize('AI assistant disconnected'))}}</span><button v-if="connection?.enabled" :aria-expanded="expanded" @click="expanded=!expanded">{{zh?'连接设置':localize('Connection settings')}}</button><span v-if="error" role="alert">{{error}}</span><div v-if="expanded&&connection?.enabled" class="assistant-settings"><label>{{zh?'本机接口':localize('Local endpoint')}}<input :value="connection.endpoint+'/v1/request'" readonly aria-label="Assistant endpoint"></label><label>{{zh?'访问令牌（本次启动有效）':localize('Access token (this session)')}}<input :type="revealed?'text':'password'" :value="connection.token" readonly aria-label="Assistant token"><button @click="revealed=!revealed">{{revealed?(zh?'隐藏':localize('Hide')):(zh?'显示':localize('Reveal'))}}</button></label><small>{{zh?'将地址和令牌填入本机助手。使用 Bearer 认证；接口支持查看项目和修改花纹、裁剪线、裁片及制作节点。关闭开关即停止连接。':localize('Use Bearer authentication in your local assistant. Read the project and edit markings, cuts, patterns and workflow nodes. Turning off the switch closes the connection.')}}</small></div></div></template>
<style scoped>.assistant-connection{padding:6px 24px;background:var(--panel-blue);border-bottom:1px solid var(--border);display:flex;gap:16px;align-items:center;flex-wrap:wrap;font-size:11px}.assistant-connection>label{display:flex;align-items:center;gap:6px;margin:0}.assistant-connection input[type=checkbox]{width:auto}.assistant-connection>span{color:var(--accent)}.assistant-connection button{padding:4px 8px;font-size:11px}.assistant-settings{width:100%;display:flex;gap:14px;flex-wrap:wrap;padding:6px 0}.assistant-settings label{display:flex;gap:8px;align-items:center;margin:0}.assistant-settings input{min-width:260px;font-size:11px;padding:5px}.assistant-settings small{width:100%;color:var(--accent)}</style>
